): HeadersInit {
  const headers: HeadersInit = {
    accept: 'gzip, deflate, br',
    'User-Agent': USER_AGENT,
    'X-Compatibility-Date': COMPATIBILITY_DATE,
  };

  // Authorization, If-None-Match, and Content-Type headers added conditionally

  return headers;
}
```

