  ...ctx,
  headers: { ...ctx.headers, 'X-Trace-Id': 'abc-123' },
}));
```

### 6. **Response Interceptor Details**
**File:** `/d/code/ESI.ts/src/core/middleware/Middleware.ts` (lines 9-18, 60-68)

```typescript
export interface ResponseContext {
  url: string;
  endpoint: string;
  method: string;
  status: number;
  headers: Record<string, string>;
  body: unknown;
  durationMs: number;
  fromCache: boolean;
}

export type ResponseInterceptor = (
  context: ResponseContext,
) => ResponseContext | Promise<ResponseContext>;
```

Called via `applyResponseInterceptors()` at line 330-358 in ApiRequestHandler.ts

### 7. **Header Parsing**
**File:** `/d/code/ESI.ts/src/core/util/headersUtil.ts` (lines 34-58)

Headers are normalized to lowercase and parsed for:
- `x-pages` (pagination)
- `etag` (caching)
- `cache-control`, `expires`, `last-modified`
- `x-cursor-before`, `x-cursor-after` (cursor pagination)
- `warning`, `x-esi-request-id`, `date`, `content-language`

### Summary of Current Flow:

```
EsiClient.constructor()
  ↓
EsiClientConfig options (including requestInterceptors)
  ↓
ApiClient instance created
  ↓
buildRequestHeaders() creates base headers
  ↓
applyRequestMiddleware() → RequestInterceptors modify headers
  ↓
fetch() executes with modified headers
  ↓
applyResponseInterceptors() processes response
```

### Integration Points for Accept-Language Header

**Three approaches (ordered by architecture preference):**

1. **Via Request Interceptor (Recommended - Existing Pattern)**
   - Add to `requestInterceptors` in EsiClientConfig
   - Modifies headers in `RequestContext`

2. **Via ApiClient Getter/Setter (Direct Config)**
   - Add `acceptLanguage?: string` to EsiClientConfig
   - Add storage & getter/setter to ApiClient
   - Modify `buildRequestHeaders()` to use the stored value

3. **Via Constant (Global Default)**
   - Add `ACCEPT_LANGUAGE` constant to constants.ts
   - Use in `buildRequestHeaders()`

All file paths are absolute and all line numbers are precise for easy reference.

